import React, { useState, useEffect } from "react";
import { Nav } from "react-bootstrap";
import { NavLink } from "react-router-dom";
import { FontAwesomeIcon } from "@fortawesome/react-fontawesome";
import { faCaretDown, faCaretUp, faImage } from "@fortawesome/free-solid-svg-icons";
import classNames from "classnames";

const SubMenuCMS = ({ icon, title, translations, userPermissions }) => {
  const [activeMenu, setActiveMenu] = useState(null); // Replaces this.state.activeMenu

  // List of menu items with permissions and translations
  const menuItems = [
    { to: "/admin/websiteInfos", label: translations.websiteInfoMenuLabel, permission: "WEBSITE_INFO_READ", key: "websiteInfos" },
    { to: "/admin/websiteFeatures", label: translations.websiteFeatureMenuLabel, permission: "WEBSITE_FEATURE_READ", key: "websiteFeatures" },
    { to: "/admin/paymentMethods", label: translations.paymentMethodMenuLabel, permission: "PAYMENT_METHOD_READ", key: "paymentMethods" },
    { to: "/admin/customerReviews", label: translations.customerReviewMenuLabel, permission: "CUSTOMER_REVIEW_READ", key: "customerReviews" },
    { to: "/admin/productRatings", label: translations.productRatingMenuLabel, permission: "PRODUCT_RATING_READ", key: "productRatings" },
    { to: "/admin/supportedPaymentGateways", label: translations.supportedPaymentGatewayMenuLabel, permission: "SUPPORTED_PAYMENT_GATEWAY_READ", key: "supportedPaymentGateways" },
    { to: "/admin/relatedProducts", label: translations.relatedProductMenuLabel, permission: "RELATED_PRODUCT_READ", key: "relatedProducts" },
    { to: "/admin/topSalesProducts", label: translations.topSalesProductMenuLabel, permission: "TOP_SALES_PRODUCT_READ", key: "topSalesProducts" },
    { to: "/admin/featuredProducts", label: translations.featuredProductMenuLabel, permission: "FEATURED_PRODUCT_READ", key: "featuredProducts" },
    { to: "/admin/brands", label: translations.brandMenuLabel, permission: "BRAND_READ", key: "brands" },
    { to: "/admin/banners", label: translations.bannerMenuLabel, permission: "BANNER_READ", key: "banners" },
    { to: "/admin/secondaryBanners", label: translations.secondaryBannerMenuLabel, permission: "SECONDARY_BANNER_READ", key: "secondaryBanners" },
  ];

  useEffect(() => {
    const currentPath = window.location.pathname;
    const pathsToMenuKey = {
      "/adminpanel/admin/websiteInfos": "websiteInfos",
      "/adminpanel/admin/websiteFeatures": "websiteFeatures",
      "/adminpanel/admin/paymentMethods": "paymentMethods",
      "/adminpanel/admin/customerReviews": "customerReviews",
      "/adminpanel/admin/productRatings": "productRatings",
      "/adminpanel/admin/supportedPaymentGateways": "supportedPaymentGateways",
      "/adminpanel/admin/relatedProducts": "relatedProducts",
      "/adminpanel/admin/topSalesProducts": "topSalesProducts",
      "/adminpanel/admin/featuredProducts": "featuredProducts",
      "/adminpanel/admin/brands": "brands",
      "/adminpanel/admin/banners": "banners",
      "/adminpanel/admin/secondaryBanners": "secondaryBanners",
    };

    const activeMenu = Object.keys(pathsToMenuKey).find((path) => currentPath.startsWith(path));
    if (activeMenu) {
      setActiveMenu(pathsToMenuKey[activeMenu]);
      toggleNavbar("cmsSettings");
    }
  }, []); // Empty dependency array to run this effect once on mount

  const toggleNavbar = (menu) => {
    setActiveMenu((prevActiveMenu) => (prevActiveMenu === menu ? null : menu));
  };

  const renderMenuItem = (to, label, icon, menuKey) => (
    <Nav.Item key={menuKey}>
      <Nav.Link as="div">
        <NavLink
          to={to}
          className={classNames("nav-link", "nav-item", { active: activeMenu === menuKey })}
        >
          <FontAwesomeIcon icon={icon} className="mr-2" />
          {label}
        </NavLink>
      </Nav.Link>
    </Nav.Item>
  );

  return (
    <Nav.Item className={classNames({ open: activeMenu })}>
      <Nav.Link
        variant="link"
        className={classNames("d-flex justify-content-between align-items-center nav-link nav-item", { active: activeMenu })}
        onClick={() => toggleNavbar("cmsSettings")}
      >
        <div>
          <FontAwesomeIcon icon={icon} className="mr-2" />
          {title}
        </div>
        <FontAwesomeIcon icon={activeMenu === "cmsSettings" ? faCaretUp : faCaretDown} />
      </Nav.Link>

      {activeMenu === "cmsSettings" && (
        <nav className="nav flex-column">
          {menuItems.map(
            (item) =>
              userPermissions.includes(item.permission) &&
              renderMenuItem(item.to, item.label, faImage, item.key)
          )}
        </nav>
      )}
    </Nav.Item>
  );
};

export default SubMenuCMS;
