import React, { useState, useEffect } from "react";
import { Nav } from "react-bootstrap";
import { NavLink } from "react-router-dom";
import { FontAwesomeIcon } from "@fortawesome/react-fontawesome";
import { faCaretDown, faCaretUp, faImage } from "@fortawesome/free-solid-svg-icons";
import classNames from "classnames";

const SubMenuSettings = ({ icon, title, translations, userPermissions }) => {
  const [activeMenu, setActiveMenu] = useState(null); // Replaces this.state.activeMenu

  const menuItems = [
    { to: "/admin/categorys", label: translations.categoryMenuLabel, permission: "CATEGORY_READ", key: "categorys" },
    { to: "/admin/subCategorys", label: translations.subCategoryMenuLabel, permission: "SUB_CATEGORY_READ", key: "subCategorys" },
    { to: "/admin/suppliers", label: translations.supplierMenuLabel, permission: "SUPPLIER_READ", key: "suppliers" },
    { to: "/admin/customers", label: translations.customerMenuLabel, permission: "CUSTOMER_READ", key: "customers" },
    { to: "/admin/variants", label: translations.variantMenuLabel, permission: "VARIANT_READ", key: "variants" },
  ];

  useEffect(() => {
    const currentPath = window.location.pathname;

    const menuKeyByPath = {
      "/adminpanel/admin/categorys": "categorys",
      "/adminpanel/admin/suppliers": "suppliers",
      "/adminpanel/admin/customers": "customers",
      "/adminpanel/admin/subCategorys": "subCategorys",
      "/adminpanel/admin/variants": "variants",
    };

    const activeMenuKey = Object.keys(menuKeyByPath).find((path) => currentPath.startsWith(path));
    if (activeMenuKey) {
      setActiveMenu(menuKeyByPath[activeMenuKey]);
      toggleNavbar("settings");
    }
  }, []); // Run once on component mount

  const toggleNavbar = (menu) => {
    setActiveMenu((prevActiveMenu) => (prevActiveMenu === menu ? null : menu));
  };

  const renderMenuItem = (to, label, menuKey) => (
    <Nav.Item key={menuKey}>
      <Nav.Link as="div">
        <NavLink
          to={to}
          className={classNames("nav-link", "nav-item", { active: activeMenu === menuKey })}
        >
          <FontAwesomeIcon icon={faImage} className="mr-2" />
          {label}
        </NavLink>
      </Nav.Link>
    </Nav.Item>
  );

  return (
    <Nav.Item className={classNames({ open: activeMenu })}>
      <Nav.Link
        variant="link"
        className={classNames("d-flex justify-content-between align-items-center nav-link nav-item", { active: activeMenu })}
        onClick={() => toggleNavbar("settings")}
      >
        <div>
          <FontAwesomeIcon icon={icon} className="mr-2" />
          {title}
        </div>
        <FontAwesomeIcon icon={activeMenu === "settings" ? faCaretUp : faCaretDown} />
      </Nav.Link>

      {activeMenu === "settings" && (
        <nav className="nav flex-column">
          {menuItems.map(
            (item) =>
              userPermissions.includes(item.permission) &&
              renderMenuItem(item.to, item.label, item.key)
          )}
        </nav>
      )}
    </Nav.Item>
  );
};

export default SubMenuSettings;
