import React, { useState, useEffect } from "react";
import { Nav } from "react-bootstrap";
import { NavLink } from "react-router-dom";
import { FontAwesomeIcon } from "@fortawesome/react-fontawesome";
import { faCaretDown, faCaretUp, faImage } from "@fortawesome/free-solid-svg-icons";
import classNames from "classnames";

const SubMenuStore = ({ icon, title, translations, userPermissions }) => {
  const [activeMenu, setActiveMenu] = useState(null); // Replaces this.state.activeMenu

  // List of menu items with permissions and translations
  const menuItems = [
    { to: "/admin/sellerStores", label: translations.sellerStoreMenuLabel, permission: "SELLER_STORE_READ", key: "sellerStores" },
    { to: "/admin/products", label: translations.productMenuLabel, permission: "PRODUCT_READ", key: "products" },

  ];

  useEffect(() => {
    const currentPath = window.location.pathname;
    const pathsToMenuKey = {
      "/adminpanel/admin/sellerStores": "sellerStores",
      "/adminpanel/admin/products": "products",
    };

    const activeMenu = Object.keys(pathsToMenuKey).find((path) => currentPath.startsWith(path));
    if (activeMenu) {
      setActiveMenu(pathsToMenuKey[activeMenu]);
      toggleNavbar("storeSettings");
    }
  }, []); // Empty dependency array to run this effect once on mount

  const toggleNavbar = (menu) => {
    setActiveMenu((prevActiveMenu) => (prevActiveMenu === menu ? null : menu));
  };

  const renderMenuItem = (to, label, icon, menuKey) => (
    <Nav.Item key={menuKey}>
      <Nav.Link as="div">
        <NavLink
          to={to}
          className={classNames("nav-link", "nav-item", { active: activeMenu === menuKey })}
        >
          <FontAwesomeIcon icon={icon} className="mr-2" />
          {label}
        </NavLink>
      </Nav.Link>
    </Nav.Item>
  );

  return (
    <Nav.Item className={classNames({ open: activeMenu })}>
      <Nav.Link
        variant="link"
        className={classNames("d-flex justify-content-between align-items-center nav-link nav-item", { active: activeMenu })}
        onClick={() => toggleNavbar("storeSettings")}
      >
        <div>
          <FontAwesomeIcon icon={icon} className="mr-2" />
          {title}
        </div>
        <FontAwesomeIcon icon={activeMenu === "storeSettings" ? faCaretUp : faCaretDown} />
      </Nav.Link>

      {activeMenu === "storeSettings" && (
        <nav className="nav flex-column">
          {menuItems.map(
            (item) =>
              userPermissions.includes(item.permission) &&
              renderMenuItem(item.to, item.label, faImage, item.key)
          )}
        </nav>
      )}
    </Nav.Item>
  );
};

export default SubMenuStore;
